using System;using System.Linq;using System.IO;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
public static class VerifyDeploy147{
 public static string Main(){var report=new System.Text.StringBuilder();foreach(var n in new[]{"house1_1","house1_2","house2_1","house2_2","house3_1","house3_2","Village_1","Village_2"}){
 var s=EditorSceneManager.NewPreviewScene();try{var root=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Locations/Enemy/"+n+".prefab"),s);var homes=root.GetComponentsInChildren<Transform>().Where(t=>t.name=="Stone_House_Open_Entrance").ToArray();var expected=n.StartsWith("Village")?10:1;if(homes.Length!=expected)throw new Exception(n+" homes="+homes.Length);
 if(root.GetComponentsInChildren<Transform>().Any(t=>t.name.StartsWith("GunStore")||t.name=="dom"||t.name.StartsWith("dom (")))throw new Exception(n+" old buildings still active");
 var sp=root.GetComponent<LocationContentSpawner>();if(sp.itemSpawnPoints.Any(p=>!p.spawnTransform)||sp.enemySpawnPoints.Any(p=>!p))throw new Exception("Null point "+n);
 var ground=GameObject.CreatePrimitive(PrimitiveType.Cube);SceneManager.MoveGameObjectToScene(ground,s);ground.transform.position=new Vector3(0,-.3f,0);ground.transform.localScale=new Vector3(800,1,800);ground.GetComponent<Renderer>().sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>("Assets/Prefabs/Workshop/Locations/House1Workshop_Ground.mat");
 foreach(var h in homes){if(Mathf.Abs(h.TransformPoint(new Vector3(0,.514f,0)).y-.26f)>.003f)throw new Exception("Floor "+n);var o=new GameObject("ControllerProbe");SceneManager.MoveGameObjectToScene(o,s);o.transform.position=h.TransformPoint(new Vector3(0,.55f,-4.6f));var src=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Player.prefab").GetComponent<CharacterController>();var c=o.AddComponent<CharacterController>();c.height=src.height;c.radius=src.radius;c.center=src.center;c.stepOffset=src.stepOffset;c.skinWidth=src.skinWidth;c.slopeLimit=src.slopeLimit;Physics.SyncTransforms();for(int i=0;i<340&&h.InverseTransformPoint(o.transform.position).z<1.3f;i++)c.Move(h.forward*.045f+Vector3.down*.025f);var p=h.InverseTransformPoint(o.transform.position);if(p.z<1.1f||!c.isGrounded)throw new Exception("Blocked "+n+" "+h.parent.name+" at "+p);UnityEngine.Object.DestroyImmediate(o);}
 if(n.StartsWith("Village")){var c=new GameObject("AuditCamera").AddComponent<Camera>();SceneManager.MoveGameObjectToScene(c.gameObject,s);c.scene=s;c.cameraType=CameraType.Preview;var target=n=="Village_1"?new Vector3(-65,0,7):new Vector3(79,0,10);c.transform.position=target+new Vector3(0,100,-85);c.transform.LookAt(target);c.orthographic=true;c.orthographicSize=70;c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=new Color(.15f,.2f,.23f);var rt=RenderTexture.GetTemporary(1500,1000,24);var last=RenderTexture.active;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;var tex=new Texture2D(1500,1000);tex.ReadPixels(new Rect(0,0,1500,1000),0,0);File.WriteAllBytes("Docs/locations/previews/"+n+"-new147.png",tex.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tex);}finally{c.targetTexture=null;RenderTexture.active=last;RenderTexture.ReleaseTemporary(rt);}}
 report.AppendLine(n+": PASS "+homes.Length+" houses entered, floor=.26, points="+sp.itemSpawnPoints.Count+"/"+sp.enemySpawnPoints.Count);
 }finally{EditorSceneManager.ClosePreviewScene(s);}}
 File.WriteAllText("Temp/verify147-result.txt",report.ToString());return report.ToString();}
}
